package api.publica;
import com.fasterxml.jackson.databind.*;import com.sun.net.httpserver.*;import config.ConfiguracionMercadoPago;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import pagos.*;import servicio.*;
public class MercadoPagoWebhookHandler {public static final String RUTA="/api/publica/pagos/mercado-pago/webhook";private final SeguridadApiPublica seguridad;private final ObjectMapper mapper;private final ValidadorFirmaMercadoPago firmas;private final WebhookMercadoPagoService servicio;public MercadoPagoWebhookHandler(SeguridadApiPublica s,ObjectMapper m,ConfiguracionMercadoPago c){this(s,m,new ValidadorFirmaMercadoPago(c.webhookSecret()),new WebhookMercadoPagoService(new dao.OrdenPagoDAOMySQL(),PasarelaPagoFactory.crear(c),new AcreditacionOrdenPagoTransaccionalService()));}public MercadoPagoWebhookHandler(SeguridadApiPublica s,ObjectMapper m,ValidadorFirmaMercadoPago f,WebhookMercadoPagoService v){seguridad=s;mapper=m;firmas=f;servicio=v;}public boolean puedeProcesar(String r){return RUTA.equals(r);}public void procesar(HttpExchange x,String metodo,String operacionId)throws IOException{if(!"POST".equals(metodo)){responder(x,405,Map.of("codigo","METODO_NO_PERMITIDO","operacionId",operacionId));return;}byte[] bytes=seguridad.leerCuerpoLimitado(x.getRequestBody());JsonNode body=mapper.readTree(bytes);String tipo=texto(body,"type");String dataId=body.path("data").path("id").asText(null);if(!"payment".equals(tipo)||dataId==null){responder(x,400,Map.of("codigo","WEBHOOK_INVALIDO","operacionId",operacionId));return;}String signature=x.getRequestHeaders().getFirst("x-signature"),requestId=x.getRequestHeaders().getFirst("x-request-id");if(!firmas.validar(signature,requestId,dataId)){responder(x,401,Map.of("codigo","FIRMA_INVALIDA","operacionId",operacionId));return;}try{var r=servicio.procesar(dataId,new String(bytes,StandardCharsets.UTF_8));responder(x,200,Map.of("recibido",true,"procesado",r.procesado(),"estado",r.estadoExterno(),"operacionId",operacionId));}catch(WebhookMercadoPagoService.ConflictoPagoException e){responder(x,409,Map.of("codigo","PAGO_INCOMPATIBLE","operacionId",operacionId));}}private String texto(JsonNode n,String k){JsonNode v=n.get(k);return v==null||v.isNull()?null:v.asText();}private void responder(HttpExchange x,int estado,Object cuerpo)throws IOException{byte[] b=mapper.writeValueAsBytes(cuerpo);x.getResponseHeaders().set("Content-Type","application/json; charset=UTF-8");x.sendResponseHeaders(estado,b.length);try(OutputStream o=x.getResponseBody()){o.write(b);}}}
